import csv,numpy as np,warnings
warnings.filterwarnings('ignore')
from pymatgen.core import Structure, Element
import networkx as nx
from pymatgen.analysis.local_env import CutOffDictNN
def units(s, anions=('S','Se','Te','As','Sb','P','Bi','I','Br','Cl')):
    idx=[i for i,st in enumerate(s) if st.specie.symbol in anions]
    sub=Structure.from_sites([s[i] for i in idx])
    els=set(st.specie.symbol for st in sub); cd={}
    for a in els:
        for b in els: cd[(a,b)]=1.15*((Element(a).atomic_radius or 1.4)+(Element(b).atomic_radius or 1.4))
    bs=CutOffDictNN(cd).get_bonded_structure(sub)
    g=nx.Graph(); g.add_nodes_from(range(len(sub)))
    for u,v,d in bs.graph.edges(data=True): g.add_edge(u,v)
    # per-unit shape tensor from bond vectors
    T=np.zeros((3,3)); nb=0; devs=[]
    for u,v in g.edges():
        # get min-image vector
        vec=sub.lattice.get_distance_and_image(sub[u].frac_coords,sub[v].frac_coords)
        d,img=vec
        c=sub.lattice.get_cartesian_coords(sub[v].frac_coords+img)-sub[u].coords
        c/=np.linalg.norm(c)
        T+=np.outer(c,c)-np.eye(3)/3; nb+=1
    if nb: 
        ev=np.sort(np.linalg.eigvalsh(T/nb)); return ev[2]-ev[0], nb, ev
    return 0,0,None
p={x['candidate_id']:x for x in csv.DictReader(open('nlo_pool.csv'))}
r=list(csv.DictReader(open('nlo_dn_train.csv')))
print('TRAIN:')
for f in ['Tl8 Te12','Cs8 Sb8','Rb8 Sb8','Cs4 Cu4 Se16','Ba2 Te6','Tl9 As3 S9','Rb12 Sb4 S12','K12 Sb4 Te12','Rb1 Sn1 Br3','Rb2 Nb4 P2 Se20']:
    for x in r:
        if x['formula']==f:
            a=units(Structure.from_str(x['poscar'],fmt='poscar')); print('%.4f %-18s aniso=%.3f nb/=%d'%(float(x['dn']),f,a[0],a[1])); break
print('POOL:')
for c in ['c007','c038','c061','c064','c089','c049','c069','c074','c079','c087','c060','c083','c062','c092','c065']:
    a=units(Structure.from_str(p[c]['poscar'],fmt='poscar')); print('%s %-20s aniso=%.3f nb=%d'%(c,p[c]['formula'],a[0],a[1]))
"

